#include <cstddef>
#include <cstdint>
#include <iostream>

class GrowingArray
{
public:
    explicit GrowingArray(std::size_t reserveBytes) : m_reserved{reserveBytes} {}
    void push(int value) {}
    std::size_t committedPages() const { return m_committedPages; }

private:
    std::size_t m_reserved;
    std::size_t m_size{};
    std::size_t m_committedPages{};
};

int main()
{
    GrowingArray a{std::size_t{1} << 30};
    for (int i{0}; i < 1000; ++i) a.push(i);
    std::cout << a.committedPages() << '\n';
}
